        sb.append("  --level LEVEL     only include lines at exactly this level (DEBUG, INFO, WARN, ERROR)\n");
        sb.append("  --top N           number of top error groups to show (default: 5)\n");
        sb.append("  --help            show this help message and exit\n");
        out.print(sb);
        out.flush();
    }
}
